declare(strict_types=1);require_once __DIR__.'/config/finance_step16.php';$error=null;$m=['legacy'=>0,'products'=>0,'customers'=>0,'sales'=>0,'receivable'=>0.0,'supplier_due'=>0.0,'stock'=>0.0,'stock_value'=>0.0,'journals'=>0,'cash_total'=>0.0,'ar'=>0.0,'ap'=>0.0,'profit'=>0.0,'pending_recon'=>0,'legacy_finance'=>0];
try{$pdo=business_db();finance_step16_ensure($pdo);finance_step16_sync_all($pdo);sales_step15_backfill($pdo);$ctx=finance_step16_context($pdo);$orgId=(int)$ctx['organization_id'];$stmt=$pdo->prepare("SELECT SUM(mapping_status='mapped') FROM raw_source_records WHERE organization_id=? AND source_dataset IN ('New UMS','Volume Points','First & Second Set','Active UMS Month_Wise','Renewal UMS','Monthely_Income','Royalty_Tracking','Extra Order for Customer')");$stmt->execute([$orgId]);$m['legacy']=(int)$stmt->fetchColumn();$stmt=$pdo->prepare("SELECT COUNT(*) FROM products WHERE organization_id=? AND status='active'");$stmt->execute([$orgId]);$m['products']=(int)$stmt->fetchColumn();$stmt=$pdo->prepare("SELECT COUNT(*) FROM crm_customers WHERE organization_id=? AND status='active'");$stmt->execute([$orgId]);$m['customers']=(int)$stmt->fetchColumn();foreach(sales_step15_sales_rows($pdo,$orgId) as $r){if($r['sale_status']!=='active')continue;$m['sales']++;$m['receivable']+=(float)$r['receivable_amount'];}foreach(purchase_step14_bill_rows($pdo,$orgId,'active') as $b){$st=purchase_step14_recalc_bill($pdo,$orgId,(int)$b['id']);$m['supplier_due']+=$st['outstanding'];}$loc=inventory_step13_location_id($pdo,$orgId);foreach(inventory_step13_stock_rows($pdo,$orgId,$loc) as $r){$m['stock']+=(float)$r['sellable_stock'];$m['stock_value']+=(float)$r['known_value'];}$accounts=finance_step16_accounts($pdo,$orgId);foreach($accounts as $a)if(!$a['is_system_clearing'])$m['cash_total']+=(float)$a['current_balance'];$control=finance_step16_control_balances($pdo,$orgId);$m['ar']=$control['accounts_receivable']??0;$m['ap']=$control['accounts_payable']??0;$pnl=finance_step16_pnl($pdo,$orgId,date('Y-m-01'),date('Y-m-t'));$m['profit']=$pnl['profit'];$stmt=$pdo->prepare("SELECT COUNT(*) FROM finance_journals WHERE organization_id=?");$stmt->execute([$orgId]);$m['journals']=(int)$stmt->fetchColumn();$stmt=$pdo->prepare("SELECT COUNT(*) FROM finance_statement_lines WHERE organization_id=? AND status='pending'");$stmt->execute([$orgId]);$m['pending_recon']=(int)$stmt->fetchColumn();$stmt=$pdo->prepare("SELECT (SELECT COUNT(*) FROM income_entries i WHERE i.organization_id=? AND i.amount>0 AND NOT EXISTS(SELECT 1 FROM finance_source_links f WHERE f.organization_id=i.organization_id AND f.source_type='legacy_income' AND f.source_id=i.id AND f.event_key='confirmed_receipt' AND f.status='active')) + (SELECT COUNT(*) FROM royalty_entries r WHERE r.organization_id=? AND r.amount>0 AND NOT EXISTS(SELECT 1 FROM finance_source_links f WHERE f.organization_id=r.organization_id AND f.source_type='legacy_royalty' AND f.source_id=r.id AND f.event_key='confirmed_receipt' AND f.status='active'))");$stmt->execute([$orgId,$orgId]);$m['legacy_finance']=(int)$stmt->fetchColumn();}catch(Throwable $e){$error=$e->getMessage();}
function d16_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function d16_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}function d16_n(mixed $v):string{$x=number_format((float)$v,3,'.','');return rtrim(rtrim($x,'0'),'.');}
